import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"签到与调度总览","description":"","frontmatter":{},"headers":[],"relativePath":"projects/lotus-plugin/docs/checkin.md","filePath":"projects/lotus-plugin/docs/checkin.md"}'),o={name:"projects/lotus-plugin/docs/checkin.md"};function r(c,l,n,s,h,p){return i(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="签到与调度总览" tabindex="-1">签到与调度总览 <a class="header-anchor" href="#签到与调度总览" aria-label="Permalink to &quot;签到与调度总览&quot;">​</a></h1><p>返回：<a href="./../README.html">项目主页</a> / <a href="./README.html">文档目录</a></p><p>签到模块按 profile 执行，包含自动签到、游戏/社区签到开关、用户通知和随机/固定调度。</p><h2 id="小功能" tabindex="-1">小功能 <a class="header-anchor" href="#小功能" aria-label="Permalink to &quot;小功能&quot;">​</a></h2><ul><li><a href="./features/checkin.html">自动签到-多 profile</a></li><li><a href="./features/scheduler.html">签到调度-随机与固定</a></li></ul><p>所有用户操作都允许在群聊执行。通知默认开启，私聊优先；若无法私聊，会在共同群聊 at 用户。</p><h2 id="支持范围" tabindex="-1">支持范围 <a class="header-anchor" href="#支持范围" aria-label="Permalink to &quot;支持范围&quot;">​</a></h2><p>游戏签到按上游能力支持：</p><ul><li>原神</li><li>星铁</li><li>绝区零</li><li>崩坏2</li><li>崩坏3</li><li>未定事件簿</li><li>崩坏：因缘精灵</li></ul><p>社区签到按米游社论坛支持：</p><ul><li>崩坏3</li><li>原神</li><li>崩坏2</li><li>未定事件簿</li><li>大别野</li><li>星铁</li><li>绝区零</li><li>崩坏：因缘精灵</li><li>星布谷地</li></ul><p>国际服和云游戏默认隐藏，只有用户绑定对应 token/cookie 后才参与。</p><h2 id="调度摘要" tabindex="-1">调度摘要 <a class="header-anchor" href="#调度摘要" aria-label="Permalink to &quot;调度摘要&quot;">​</a></h2><p>随机模式会在前一天生成次日计划，把用户平均分布在 <code>00:00-23:30</code>。计划生成后会给用户发送签到时间图片。当天新注册的 profile 会补入当日计划，不会重新洗牌。</p><p>锅巴面板和配置文件中的定时任务使用七段 cron，例如 <code>0 0 0 * * ? *</code> 表示每天 00:00 生成次日计划。插件启动后会检查是否错过当天的计划生成时间；如果已过时间但明日计划不存在，会自动补生成。</p>',15)])])}const f=e(o,[["render",r]]);export{u as __pageData,f as default};
